        const fakeT = target ? Object.assign({}, target, { def: combatDef(target), sdef: combatSdef(target) }) : target;
        let dmg = (abId === "strike") ? window.Entities.strikeDmg(fakeC, fakeT) : window.Entities.abilityDmg(fakeC, abId, fakeT);
