        // Strength flurry: +0.5% flurry damage per point (sprint-flurry swings,
        // wave-ride swings, follow-throughs, and the Viper Flurry technique).
        try {
          const isFlurryTech = abId === "viper_flurry";
          if ((opts.flurry || isFlurryTech) && caster && window.Entities && window.Entities.flurryDmgMult) {
            dmg = Math.max(1, Math.round(dmg * window.Entities.flurryDmgMult(caster)));
          }
        } catch (e) { }
