          const k = pi / 9;
          G.particles.push({ x: ox + (ex - ox) * k + (Math.random() - 0.5) * 0.7, y: oy + (ey - oy) * k + (Math.random() - 0.5) * 0.7, t: 0, life: 3 + Math.random(), delay: 0.1 * pi, color: pi % 2 ? "#2e6b34" : "#3fa34d" });
