        life: 14 / 16, from, src: caster, dmg, abId: "comet_shot", mastery: masteryT, magic: true,
        color: "#ff7b2e", shape: "spear", size: 2.0, core: "#fff3c4", glow: "#ff3d2e",
        trail: ["#ff7b2e", "#ffc93d", "#ff3d2e"], trailAcc: 0, pass: true, hit: [],
        waveR: 0, splash: { r: masteryT ? 2 : 1.5, mult: 0.5 }, boom: { ring: "#ffb02e", n: 18 },
        status: { type: "burn", chance: 1, dps: masteryT ? 9 : 6, potency: 1.2 },
