  function isFrozenNow(f) { try { return (window.Status && (window.Status.isFrozen(f) || window.Status.has(f, "freeze"))); } catch (e) { return false; } }
  function isBurningNow(f) { try { return (window.Status && window.Status.has(f, "burn")); } catch (e) { return false; } }
