      const p = G.player; if (!p) return own;
      const myDim = playerDim();
      const dlvl = ((p.dungeonLevel | 0) || 1);
      let rems = null;
      try { rems = window.MP.getRemotes ? window.MP.getRemotes() : null; } catch (e) { rems = null; }
