      try { r = window.Items.useItem(p, slot.id, slot); } catch (e) { r = { ok: false, msg: "Nothing happens." }; }
      if (r && r.msg) try { window.UI.toast(r.msg, 2500); } catch (e) { }
      try { window.UI.updateHUD(); window.UI.updateHotbar(); window.Game.saveGame(true); } catch (e) { }
