              try { if (Math.hypot(p.x - m.x, p.y - m.y) > 2.0) voidTeleportNear(m, p.x, p.y, 1.0, 1.8); } catch (e2) {}
              try { addParticles(m.x, m.y, "#7a4ae0", 12); window.UI.toast(`👁️ Peter steps out of the dark!`, 2200); } catch (e3) {}
