            q.innerHTML = "<span><b>Goddess of Dawn:</b> It is done, hero. The <b>Supreme Overlord of Hell</b> has fallen by your hand, and the dark below loosens its grip on the world. Come — I carry you home to where your journey began.</span>";
            log.appendChild(q);
            const b = document.createElement("button");
            b.textContent = "✨ Return to my first home";
