        try {
          if (a.region) { for (const f of a.flips) d.tiles[f.i] = f.orig; }
          else if (d.tiles[a.y * d.w + a.x] === a.temp) d.tiles[a.y * d.w + a.x] = a.orig;
        } catch (e) { }
        act.splice(k, 1);
