        ctx.globalAlpha = Math.max(0, a) * 0.9; ctx.fillStyle = "#efe6c8";
        ctx.beginPath(); ctx.ellipse(-lr * 0.2, -lr * 0.9 * flap, lr * 0.9, lr * 0.35, flap * 0.5, 0, 7); ctx.fill();
