        ctx.beginPath(); ctx.arc(sx, sy, Math.max(1, pr1), 0, 7); ctx.fill();
        ctx.globalAlpha = Math.max(0, a) * 0.25 * (pt.alpha || 1);
        ctx.fillStyle = "#ffffff";
