            for (let ci = 1; ci < pts.length; ci++) ctx.lineTo(pts[ci][0] * ts + ox, pts[ci][1] * ts + oy);
            ctx.stroke();
            ctx.strokeStyle = pt.color || "#3a2c1e"; ctx.lineWidth = Math.max(1.5, 2.5 * zoom / 1.8);
